import React, { useEffect, useRef, useState } from 'react';
import { Box, Button, Paper, Typography } from '@mui/material';
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { DEMO_VENUES, DemoVenue, VenueKind, VenuePerson } from '../data/venues';
import { RealmPortal } from '../contexts/RealmContext';
import { REFILL_STATIONS, RefillStation } from '../data/stations';
import { GLOW_THEMES, buzzForVenue, venueHasLiveBuzz } from '../data/venueBuzz';
import { STATUS_META } from '../utils/presence';
import { useThemeMode } from '../contexts/ThemeModeContext';
import { elementColor, elementEmoji, resolveNavitarArt } from '../utils/navitarArt';
import type { WildSpawn } from '../pages/RealmMap';
import {
  STYLE_URLS,
  addBuildingsLayer,
  escapeHtml,
  markerLabel,
  markerShell,
  wrapMarker,
} from './StrollMap3D';

// WORLD MAP 3D VIEW (Round 21, Eddie 2026-11-18: "Build it now —
// add the 3D prototype view to the World Map").
//
// The MapLibre 3D view from the Glacier World Map prototype — real
// streets tilted with extruded buildings — lived only inside
// Stroll (Round 12's StrollMap3D). This is the same view on the
// main World Map (/map), beside the classic Leaflet map, which
// STAYS permanently (Round 12 ruling; the R11.1 tile lesson is
// law — the classic tiles are never re-themed).
//
// SHARED CORE, NOT A COPY: the style pair, the buildings layer and
// the marker shells are imported from StrollMap3D. What differs is
// the data + interaction contract, and that difference is the
// point of this component:
//
// - RealmMap (the page) owns ALL interaction state — selected
//   venue, meet person, check-in, the wild/station/Joe cards, the
//   notification handoffs. That state lives ABOVE the view switch,
//   so this component is a pure view: it renders the page's data
//   and reports marker taps back through callbacks that drive the
//   very same page state the Leaflet markers drive. The venue
//   card, Who's Here and the meet card render below the map in
//   page JSX and work identically in both views; the Round 17
//   handoffs (venue focus, icebreaker meet) resolve through page
//   state + the flyTarget prop, so they are honored with the 3D
//   view mounted exactly as with the classic map.
// - The player position is the page's own (its geolocation watch
//   and Find-me set it) — no second GPS watch here.
// - Layers the Stroll view doesn't have: roaming wild spawns
//   (positions stream in as props from the page's drift state),
//   refill stations, Joe's arena, and the page's heat / friend-pin
//   layer toggles.
//
// Marker emoji maps mirror RealmMap's VENUE_EMOJI / PORTAL_EMOJI
// (kept local on purpose: importing them from the page would make
// a runtime import cycle with the page's lazy import of this
// component — the R2 TDZ lesson).

const PORTAL_EMOJI: Record<string, string> = {
  ice: '❄️',
  fire: '🔥',
  nature: '🌿',
  shadow: '🌑',
  light: '✨',
  quantum: '🌌',
  electric: '⚡',
  spiritual: '🕊️',
  water: '💧',
};

const VENUE_EMOJI: Record<VenueKind, string> = {
  bar: '🍺',
  park: '🌳',
  beach: '🏖️',
};

// Same home base as RealmMap's LA_CENTER ([lat, lng] there).
const LA_CENTER: [number, number] = [-118.44, 34.1]; // [lng, lat]
// STREET LEVEL (Eddie, 2026-11-18, Round 21 addition): "the map
// needs to be street level for walking experience." The 3D view
// OPENS on the player's own position at walking zoom — close
// enough that the extruded buildings stand around them — pitched
// like the prototype. It is a walking/navigation camera, never a
// zoomed-out city overview (that framing is the classic map's
// job, one tap away on the toggle).
const ENTRY_PITCH = 58;
const STREET_ZOOM = 16.5;
// Companion gap: RealmMap's COMPANION_GAP_PX is 64px centre to
// centre; each axis gets gap / √2 (southeast, down-right on screen).
const COMPANION_OFFSET_PX = 64 / Math.SQRT2;

export interface WorldMap3DCompanion {
  name: string;
  element: string;
  imageUrl?: string | null;
  level: number;
  hp: number;
  maxHp: number;
  checkedInName?: string | null;
}

export interface WorldMap3DFriendPin {
  person: VenuePerson;
  venue: DemoVenue;
  slot: number;
}

interface WorldMap3DProps {
  portals: RealmPortal[];
  onPortalClick: (portal: RealmPortal) => void;
  onVenueClick: (venue: DemoVenue) => void;
  heatBlobs: { venue: DemoVenue; density: number }[];
  showHeat: boolean;
  friendPins: WorldMap3DFriendPin[];
  showFriendPins: boolean;
  onFriendClick: (venue: DemoVenue) => void;
  wildSpawns: WildSpawn[];
  onWildClick: (spawn: WildSpawn) => void;
  onStationClick: (station: RefillStation) => void;
  joePosition: [number, number]; // [lat, lng] — RealmMap's JOE_ARENA
  onJoeClick: () => void;
  playerPos: [number, number]; // [lat, lng]
  companion: WorldMap3DCompanion | null;
  flyTarget: { lat: number; lng: number; nonce: number } | null;
  resetSignal: number;
  onLocated: (lat: number, lng: number) => void;
  locateFallback: { lat: number; lng: number; label: string };
  onFallback: (label: string) => void;
  locateNote: string | null;
}

const WorldMap3D: React.FC<WorldMap3DProps> = props => {
  const { mode } = useThemeMode();
  const modeRef = useRef(mode);
  modeRef.current = mode;
  const containerRef = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const [styleReady, setStyleReady] = useState(false);

  // Live mirrors of the props the imperative map code reads — the
  // page re-renders often and its callbacks are fresh closures
  // every render; the markers must call the latest ones.
  const propsRef = useRef(props);
  propsRef.current = props;
  const playerPosRef = useRef<[number, number]>(props.playerPos);
  const flyTargetRef = useRef(props.flyTarget);
  flyTargetRef.current = props.flyTarget;

  const playerMarkerRef = useRef<maplibregl.Marker | null>(null);
  const companionMarkerRef = useRef<maplibregl.Marker | null>(null);
  const companionPosRef = useRef<[number, number] | null>(null);
  const companionTargetRef = useRef<[number, number] | null>(null);
  const heatMarkersRef = useRef(new Map<string, maplibregl.Marker>());
  const friendMarkersRef = useRef(new Map<string, maplibregl.Marker>());
  const wildMarkersRef = useRef(new Map<string, maplibregl.Marker>());
  const framePlayerRef = useRef<((duration: number) => void) | null>(null);
  // Follow (StrollMap3D's discipline): the camera keeps the player
  // framed while follow is on; a drag turns it off until Find me
  // or Reset view turns it back on.
  const followRef = useRef(true);
  const [follow, setFollow] = useState(true);

  // ---- main init (once) ----
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    const [startLat, startLng] = playerPosRef.current;
    const map = new maplibregl.Map({
      container,
      style: STYLE_URLS[modeRef.current],
      center: [startLng, startLat],
      zoom: STREET_ZOOM,
      pitch: ENTRY_PITCH,
      bearing: 0,
      attributionControl: { compact: true },
    });
    mapRef.current = map;
    map.addControl(new maplibregl.NavigationControl({ visualizePitch: true }), 'bottom-right');
    map.touchPitch.enable();
    map.dragRotate.enable();
    // The opening frame, recorded on the container (the moveend
    // listener below keeps it current) — the street-level opening
    // is provable from the DOM without reaching into the map.
    container.dataset.camera =
      `${startLng.toFixed(5)},${startLat.toFixed(5)} ` +
      `z${map.getZoom().toFixed(2)} p${Math.round(map.getPitch())}`;

    const noteBuildings = () => {
      addBuildingsLayer(map, modeRef.current === 'dark');
      if (map.getLayer('glacer-buildings')) container.dataset.buildings = 'on';
    };
    map.on('style.load', () => {
      container.dataset.styleLoaded = 'true';
      setStyleReady(true);
      noteBuildings();
    });
    map.on('moveend', () => {
      const c = map.getCenter();
      container.dataset.camera =
        `${c.lng.toFixed(5)},${c.lat.toFixed(5)} ` +
        `z${map.getZoom().toFixed(2)} p${Math.round(map.getPitch())}`;
    });

    // Street-level framing on the player — the view's home
    // camera (opening frame, Reset view, Find me all land here).
    const framePlayer = (duration: number) => {
      const [lat, lng] = playerPosRef.current;
      map.flyTo({ center: [lng, lat], zoom: STREET_ZOOM, pitch: ENTRY_PITCH, duration });
    };
    framePlayerRef.current = framePlayer;

    map.on('dragstart', () => {
      followRef.current = false;
      setFollow(false);
    });

    map.on('load', () => {
      // A notification handoff may have set a fly target before
      // the map finished loading — it wins over the street-level
      // home frame (and is itself flown at street level).
      const ft = flyTargetRef.current;
      if (ft) {
        container.dataset.flyTarget = `${ft.lat},${ft.lng} z16`;
        map.flyTo({ center: [ft.lng, ft.lat], zoom: 16, pitch: ENTRY_PITCH, duration: 0 });
      }
    });

    // ----- static layers: venues, portals, stations, Joe -----
    // (Their datasets are the demo sets the page mounts with —
    // the same discipline as StrollMap3D's init layers.)

    // Demo venues — element-colour disc with the KIND emoji, like
    // the 2D venue icon; a live-buzz venue gets a gold glow ring
    // (the 2D map's animated CSS glow themes are Leaflet-side; the
    // 3D read is ring + the theme named in the popup).
    DEMO_VENUES.forEach(venue => {
      const buzz = buzzForVenue(venue.id);
      const live = venueHasLiveBuzz(buzz);
      const pin = markerShell(40, live ? '#ffd76a' : '#ffffff', elementColor(venue.element));
      if (live) pin.style.boxShadow = '0 0 18px 7px rgba(255, 183, 77, 0.75)';
      pin.style.fontSize = '22px';
      pin.textContent = VENUE_EMOJI[venue.kind];
      const el = wrapMarker(pin, markerLabel(venue.name, '#ffffff'));
      el.dataset.mapMarker = 'venue';
      el.dataset.venueId = venue.id;
      el.addEventListener('click', () => propsRef.current.onVenueClick(venue));
      new maplibregl.Marker({ element: el })
        .setLngLat([venue.lng, venue.lat])
        .setPopup(
          new maplibregl.Popup({ offset: 26, closeButton: false }).setHTML(
            `<strong>${VENUE_EMOJI[venue.kind]} ${escapeHtml(venue.name)}</strong><br/>` +
              `${escapeHtml(venue.area)} · ${escapeHtml(venue.tagline)}<br/>` +
              (live
                ? `${GLOW_THEMES[buzz!.glowTheme].emoji} Glowing: ${GLOW_THEMES[buzz!.glowTheme].name}<br/>`
                : '') +
              `Tap the venue card below for perks &amp; who's here.`
          )
        )
        .addTo(map);
    });

    // Portals (RealmContext — the same list the 2D map draws).
    propsRef.current.portals.forEach(portal => {
      const pin = markerShell(34, '#ffd76a', '#0a2531');
      pin.style.fontSize = '19px';
      pin.textContent = PORTAL_EMOJI[portal.type] || '🌀';
      const el = wrapMarker(pin, markerLabel(portal.name, '#ffd76a'));
      el.dataset.mapMarker = 'portal';
      el.dataset.portalId = portal.id;
      el.addEventListener('click', () => propsRef.current.onPortalClick(portal));
      new maplibregl.Marker({ element: el })
        .setLngLat([portal.location.lng, portal.location.lat])
        .setPopup(
          new maplibregl.Popup({ offset: 24, closeButton: false }).setHTML(
            `<strong>${PORTAL_EMOJI[portal.type] || '🌀'} ${escapeHtml(portal.name)}</strong><br/>` +
              `Type: ${escapeHtml(portal.type)} · Level ${portal.level}<br/>` +
              `${portal.isActive ? 'Active' : 'Inactive'}` +
              (portal.specialFusion
                ? `<br/>Fusion: ${escapeHtml(portal.specialFusion.fusionName)} (${portal.specialFusion.energyCost} energy)`
                : '')
          )
        )
        .addTo(map);
    });

    // Refill stations — teal potion discs, the 2D station look.
    REFILL_STATIONS.forEach(station => {
      const pin = markerShell(40, '#ffffff', '#009688');
      pin.style.fontSize = '22px';
      pin.textContent = '🧪';
      const el = wrapMarker(pin, markerLabel(station.name, '#ffffff'));
      el.dataset.mapMarker = 'station';
      el.dataset.stationId = station.id;
      el.addEventListener('click', () => propsRef.current.onStationClick(station));
      new maplibregl.Marker({ element: el })
        .setLngLat([station.lng, station.lat])
        .setPopup(
          new maplibregl.Popup({ offset: 26, closeButton: false }).setHTML(
            `<strong>🧪 ${escapeHtml(station.name)}</strong><br/>` +
              `Refill station · ${escapeHtml(station.kind ?? 'supplies')}<br/>` +
              `Tap the station card below to collect potions.`
          )
        )
        .addTo(map);
    });

    // Joe's arena — the gold mic marker by the Observatory.
    {
      const [jLat, jLng] = propsRef.current.joePosition;
      const pin = markerShell(40, '#ffffff', '#FFC107');
      pin.style.fontSize = '22px';
      pin.textContent = '🎙️';
      const el = wrapMarker(pin, markerLabel('JOE', '#FFC107'));
      el.dataset.mapMarker = 'joe';
      el.addEventListener('click', () => propsRef.current.onJoeClick());
      new maplibregl.Marker({ element: el })
        .setLngLat([jLng, jLat])
        .setPopup(
          new maplibregl.Popup({ offset: 26, closeButton: false }).setHTML(
            `<strong>🎙️ Navitar Zero — Judge &amp; Announcer</strong><br/>` +
              `The Impossible Challenger<br/>Tap the card below to take him on.`
          )
        )
        .addTo(map);
    }

    // Player marker — the page's position (GPS when known, home
    // base otherwise), exactly the 2D map's playerPos.
    const playerEl = document.createElement('div');
    playerEl.dataset.mapMarker = 'player';
    playerEl.style.cssText =
      'width:18px;height:18px;border-radius:50%;background:#1a86e8;border:3px solid #fff;' +
      'box-shadow:0 0 0 6px rgba(26,134,232,0.25),0 2px 8px rgba(0,0,0,0.4)';
    const [pLat, pLng] = playerPosRef.current;
    playerMarkerRef.current = new maplibregl.Marker({ element: playerEl })
      .setLngLat([pLng, pLat])
      .setPopup(
        new maplibregl.Popup({ offset: 18, closeButton: false }).setHTML(
          '<strong>You are here</strong>'
        )
      )
      .addTo(map);

    // Companion trailing — the 2D map's math: the companion sits
    // ~64px southeast of the player on screen, eased toward it.
    const updateCompanionTarget = () => {
      const [lat, lng] = playerPosRef.current;
      const p = map.project([lng, lat]);
      const ll = map.unproject([p.x + COMPANION_OFFSET_PX, p.y + COMPANION_OFFSET_PX]);
      companionTargetRef.current = [ll.lng, ll.lat];
      if (!companionPosRef.current) {
        companionPosRef.current = [ll.lng, ll.lat];
        companionMarkerRef.current?.setLngLat(companionPosRef.current);
      }
    };
    map.on('moveend', updateCompanionTarget);
    map.on('zoomend', updateCompanionTarget);
    updateCompanionTarget();

    const trail = window.setInterval(() => {
      const cur = companionPosRef.current;
      const tgt = companionTargetRef.current;
      const marker = companionMarkerRef.current;
      if (!cur || !tgt || !marker) return;
      const dLng = tgt[0] - cur[0];
      const dLat = tgt[1] - cur[1];
      if (Math.abs(dLng) < 1e-7 && Math.abs(dLat) < 1e-7) return;
      const next: [number, number] = [cur[0] + dLng * 0.22, cur[1] + dLat * 0.22];
      companionPosRef.current = next;
      marker.setLngLat(next);
    }, 120);

    return () => {
      window.clearInterval(trail);
      map.remove();
      mapRef.current = null;
      playerMarkerRef.current = null;
      companionMarkerRef.current = null;
      companionPosRef.current = null;
      companionTargetRef.current = null;
      heatMarkersRef.current.clear();
      friendMarkersRef.current.clear();
      wildMarkersRef.current.clear();
    };
    // Init once — dynamic data syncs through the effects below.
  }, []);

  // ---- theme follow: swap the GL style (buildings re-add via the
  // style.load listener registered in init) ----
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    map.setStyle(STYLE_URLS[mode]);
  }, [mode]);

  // ---- player position (the page's GPS / Find-me state) ----
  useEffect(() => {
    playerPosRef.current = props.playerPos;
    const [lat, lng] = props.playerPos;
    // Recorded on the container like StrollMap3D records its GPS
    // fixes — the position data path stays observable even where
    // the GL render loop can't run.
    if (containerRef.current) {
      containerRef.current.dataset.playerPos = `${lat},${lng}`;
    }
    playerMarkerRef.current?.setLngLat([lng, lat]);
    const map = mapRef.current;
    if (map) {
      const p = map.project([lng, lat]);
      const ll = map.unproject([p.x + COMPANION_OFFSET_PX, p.y + COMPANION_OFFSET_PX]);
      companionTargetRef.current = [ll.lng, ll.lat];
      if (!companionPosRef.current) {
        companionPosRef.current = [ll.lng, ll.lat];
        companionMarkerRef.current?.setLngLat(companionPosRef.current);
      }
      // Follow: a real position update keeps the player framed at
      // street level (centre-only ease — the street zoom set by
      // the opening frame / Find me / Reset is preserved, exactly
      // StrollMap3D's follow discipline).
      if (followRef.current) {
        map.easeTo({ center: [lng, lat], duration: 600 });
      }
    }
  }, [props.playerPos]);

  // ---- companion marker sync (the Navidex pick is the single
  // source of truth — same discipline as StrollMap3D) ----
  const companion = props.companion;
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    companionMarkerRef.current?.remove();
    companionMarkerRef.current = null;
    if (!companion) {
      companionPosRef.current = null;
      return;
    }
    const pin = markerShell(52, elementColor(companion.element), '#0a2531');
    if (companion.imageUrl) {
      const img = document.createElement('img');
      img.src = companion.imageUrl;
      img.alt = '';
      img.style.cssText = 'width:100%;height:100%;object-fit:cover;';
      pin.appendChild(img);
    } else {
      pin.style.fontSize = '24px';
      pin.textContent = elementEmoji(companion.element);
    }
    const el = wrapMarker(pin, markerLabel(companion.name, '#ffffff'));
    el.dataset.mapMarker = 'companion';
    companionMarkerRef.current = new maplibregl.Marker({ element: el })
      .setLngLat(companionPosRef.current ?? companionTargetRef.current ?? LA_CENTER)
      .setPopup(
        new maplibregl.Popup({ offset: 28, closeButton: false }).setHTML(
          `<strong>${elementEmoji(companion.element)} ${escapeHtml(companion.name)}</strong><br/>` +
            `Your companion · Lv. ${companion.level} · ${escapeHtml(companion.element)}<br/>` +
            `HP ${companion.hp}/${companion.maxHp}` +
            (companion.checkedInName
              ? `<br/>Checked in at ${escapeHtml(companion.checkedInName)}`
              : '')
        )
      )
      .addTo(map);
    // Identity fields only: level/HP refreshes ride the page's own
    // surfaces (the companion panel below the map) rather than
    // rebuilding the marker mid-walk.
  }, [companion?.name, companion?.element, companion?.imageUrl]);

  // ---- heat glow sync (privacy law: blobs only, never pins) ----
  const heatKey =
    (props.showHeat ? 'on' : 'off') +
    '|' +
    props.heatBlobs.map(h => `${h.venue.id}:${h.density}`).join(',');
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    const registry = heatMarkersRef.current;
    const wanted = new Map<string, { venue: DemoVenue; density: number }>();
    if (propsRef.current.showHeat) {
      propsRef.current.heatBlobs.forEach(h => wanted.set(h.venue.id, h));
    }
    [...registry.keys()].forEach(id => {
      if (!wanted.has(id)) {
        registry.get(id)?.remove();
        registry.delete(id);
      }
    });
    wanted.forEach(({ venue, density }, id) => {
      if (registry.has(id)) return;
      // Same sizing as the 2D heatIcon (90 + 26/person, cap 190).
      const size = Math.min(190, 90 + density * 26);
      const el = document.createElement('div');
      el.dataset.mapMarker = 'heat';
      el.dataset.venueId = id;
      el.style.cssText =
        `width:${size}px;height:${size}px;border-radius:50%;pointer-events:none;` +
        'background:radial-gradient(circle, rgba(64,224,138,0.4) 0%, rgba(64,224,138,0.16) 45%, rgba(64,224,138,0) 70%);';
      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([venue.lng, venue.lat])
        .addTo(map);
      registry.set(id, marker);
    });
    // heatKey captures the meaningful inputs (toggle + id:density set).
  }, [heatKey]);

  // ---- friend pin sync (the ONLY individual people markers) ----
  const friendKey =
    (props.showFriendPins ? 'on' : 'off') + '|' + props.friendPins.map(f => f.person.id).join(',');
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    const registry = friendMarkersRef.current;
    const wanted = new Map<string, WorldMap3DFriendPin>();
    if (propsRef.current.showFriendPins) {
      propsRef.current.friendPins.forEach(f => wanted.set(f.person.id, f));
    }
    [...registry.keys()].forEach(id => {
      if (!wanted.has(id)) {
        registry.get(id)?.remove();
        registry.delete(id);
      }
    });
    wanted.forEach(({ person, venue, slot }, id) => {
      if (registry.has(id)) return;
      const pin = markerShell(40, '#7be2ae', '#0a2531');
      if (person.navitarImage) {
        const img = document.createElement('img');
        img.src = person.navitarImage;
        img.alt = '';
        img.style.cssText = 'width:100%;height:100%;object-fit:cover;';
        pin.appendChild(img);
      } else {
        pin.style.fontSize = '20px';
        pin.textContent = elementEmoji(person.navitarElement);
      }
      const el = wrapMarker(pin, markerLabel(person.name, '#7be2ae'));
      el.dataset.mapMarker = 'friend';
      el.dataset.personId = id;
      el.addEventListener('click', () => propsRef.current.onFriendClick(venue));
      // The 2D map's exact fan offsets for friends at one venue.
      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([
          venue.lng + 0.0022 * (Math.floor(slot / 2) * 2 - 1) + 0.0016,
          venue.lat + 0.0016 * ((slot % 2) * 2 - 1),
        ])
        .setPopup(
          new maplibregl.Popup({ offset: 26, closeButton: false }).setHTML(
            `<strong>${escapeHtml(person.name)}</strong> — your friend<br/>` +
              `${escapeHtml(person.navitarName)} (Lv. ${person.navitarLevel} · ${escapeHtml(person.navitarElement)}) · ${STATUS_META[person.networkingStatus].label}<br/>` +
              `Tap the venue card below to meet up.`
          )
        )
        .addTo(map);
      registry.set(id, marker);
    });
  }, [friendKey]);

  // ---- wild spawn sync (positions stream from the page's drift
  // state; markers are added/removed/moved, never rebuilt) ----
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    const registry = wildMarkersRef.current;
    const seen = new Set<string>();
    props.wildSpawns.forEach(spawn => {
      seen.add(spawn.id);
      const existing = registry.get(spawn.id);
      if (existing) {
        existing.setLngLat([spawn.lng, spawn.lat]);
        return;
      }
      const wild = spawn.wild;
      const art = resolveNavitarArt(wild.imageUrl, wild.name);
      const pin = markerShell(56, '#FFC107', '#121212');
      if (art) {
        const img = document.createElement('img');
        img.src = art;
        img.alt = '';
        img.style.cssText = 'width:100%;height:100%;object-fit:cover;display:block;';
        pin.appendChild(img);
      } else {
        pin.style.fontSize = '28px';
        pin.textContent = elementEmoji(wild.element);
      }
      const wrap = document.createElement('div');
      wrap.style.cssText = 'display:flex;flex-direction:column;align-items:center;';
      wrap.appendChild(pin);
      wrap.appendChild(markerLabel(wild.name, '#ffffff'));
      const wildTag = document.createElement('div');
      wildTag.textContent = 'WILD';
      wildTag.style.cssText =
        'text-align:center;font-size:10px;font-weight:bold;color:#FFC107;' +
        'text-shadow:0 1px 3px rgba(0,0,0,0.8);white-space:nowrap;';
      wrap.appendChild(wildTag);
      wrap.dataset.mapMarker = 'wild';
      wrap.dataset.spawnId = spawn.id;
      const spawnId = spawn.id;
      wrap.addEventListener('click', () => {
        // The freshest copy of the spawn (it drifts) — the page's
        // own state is the source, like a tap on the 2D marker.
        const cur = propsRef.current.wildSpawns.find(s => s.id === spawnId);
        if (cur) propsRef.current.onWildClick(cur);
      });
      const marker = new maplibregl.Marker({ element: wrap })
        .setLngLat([spawn.lng, spawn.lat])
        .addTo(map);
      registry.set(spawn.id, marker);
    });
    [...registry.keys()].forEach(id => {
      if (!seen.has(id)) {
        registry.get(id)?.remove();
        registry.delete(id);
      }
    });
  }, [props.wildSpawns]);

  // ---- fly-to (venue rows, portal rows, notification handoffs —
  // all of them set the page's flyTarget; the nonce re-flies a
  // repeat tap on the same place) ----
  const flyNonce = props.flyTarget?.nonce ?? 0;
  useEffect(() => {
    if (!flyNonce) return;
    const ft = flyTargetRef.current;
    const map = mapRef.current;
    if (!ft || !map) return;
    if (containerRef.current) {
      containerRef.current.dataset.flyTarget = `${ft.lat},${ft.lng} z16`;
    }
    map.flyTo({ center: [ft.lng, ft.lat], zoom: 16, pitch: ENTRY_PITCH, duration: 900 });
  }, [flyNonce]);

  // ---- reset view: the classic map's Reset re-frames the whole
  // demo map; the 3D view's Reset returns to ITS home frame —
  // street level on the player, following again. ----
  const resetSignal = props.resetSignal;
  const firstResetRef = useRef(true);
  useEffect(() => {
    if (firstResetRef.current) {
      firstResetRef.current = false;
      return;
    }
    followRef.current = true;
    setFollow(true);
    framePlayerRef.current?.(800);
  }, [resetSignal]);

  // ---- Find me / Reset view: the classic map's overlay controls,
  // same look, same fallback honesty (no GPS → centre on the
  // checked-in venue or home base and SAY so). ----
  const useFallback = () => {
    const map = mapRef.current;
    const fb = propsRef.current.locateFallback;
    map?.flyTo({ center: [fb.lng, fb.lat], zoom: 16, pitch: ENTRY_PITCH, duration: 900 });
    propsRef.current.onFallback(fb.label);
  };
  const findMe = () => {
    if (!navigator.geolocation) {
      useFallback();
      return;
    }
    navigator.geolocation.getCurrentPosition(
      pos => {
        const { latitude, longitude } = pos.coords;
        propsRef.current.onLocated(latitude, longitude);
        followRef.current = true;
        setFollow(true);
        mapRef.current?.flyTo({
          center: [longitude, latitude],
          zoom: STREET_ZOOM,
          pitch: ENTRY_PITCH,
          duration: 1000,
        });
      },
      () => useFallback()
    );
  };
  const resetView = () => {
    followRef.current = true;
    setFollow(true);
    framePlayerRef.current?.(800);
  };

  return (
    <Box sx={{ width: '100%', height: '100%', position: 'relative', bgcolor: '#0a2531' }}>
      <div
        ref={containerRef}
        data-testid="world-map3d"
        style={{ position: 'absolute', inset: 0 }}
      />
      {!styleReady && (
        <div
          style={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%,-50%)',
            zIndex: 5,
            pointerEvents: 'none',
          }}
        >
          <Paper sx={{ px: 2, py: 1, bgcolor: 'rgba(18,18,18,0.85)' }}>
            <Typography variant="body2">Loading 3D map…</Typography>
          </Paper>
        </div>
      )}
      <div
        style={{
          position: 'absolute',
          top: 10,
          right: 10,
          zIndex: 5,
          display: 'flex',
          flexDirection: 'column',
          gap: 8,
          alignItems: 'flex-end',
        }}
      >
        <Button
          variant={follow ? 'contained' : 'outlined'}
          color="primary"
          onClick={findMe}
          sx={follow ? undefined : { bgcolor: 'rgba(18,18,18,0.85)' }}
        >
          📍 Find me
        </Button>
        <Button
          variant="outlined"
          size="small"
          onClick={resetView}
          sx={{ bgcolor: 'rgba(18,18,18,0.85)' }}
        >
          Reset view
        </Button>
        {props.locateNote && (
          <Paper sx={{ px: 1.5, py: 0.75, bgcolor: 'rgba(18,18,18,0.85)', maxWidth: 240 }}>
            <Typography variant="caption">{props.locateNote}</Typography>
          </Paper>
        )}
      </div>
      <Box
        sx={{
          position: 'absolute',
          left: 12,
          top: 12,
          zIndex: 4,
          px: 1.25,
          py: 0.5,
          borderRadius: 999,
          bgcolor: 'rgba(6, 24, 33, 0.55)',
          pointerEvents: 'none',
          maxWidth: '62%',
        }}
      >
        <Typography variant="caption" sx={{ color: '#e8f6fb' }}>
          3D streets at street level — tap a marker and its card opens below, same as the classic
          map
        </Typography>
      </Box>
    </Box>
  );
};

export default WorldMap3D;
